// Package store provides typed repository wrappers for the database.
//
// In production these would be generated by sqlc from queries/*.sql +
// migrations/*.sql. We hand-write the same shape here so the project builds
// without requiring sqlc to be installed; when sqlc becomes available the
// generated `internal/store/sqlc/` package can replace these files 1:1.
//
// All read methods that touch tenant-scoped tables also expose
// `*ByTenant(ctx, tenantID, ...)` variants that pull tenant_id from
// context.Context via the tenant package. The store layer is the
// LAST line of defense against forgetting the tenant scope — the
// service layer should already have set it via auth middleware.
package store

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// DBTX is the minimal interface satisfied by both *pgxpool.Pool and pgx.Tx.
// Lets repo methods run inside or outside a transaction.
type DBTX interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// FromPool wraps a pool so it satisfies DBTX.
func FromPool(p *pgxpool.Pool) DBTX { return p }

// Store aggregates all per-table repositories.
type Store struct {
	Pool           *pgxpool.Pool
	Users          *UserRepo
	Tenants        *TenantRepo
	Memberships    *MembershipRepo
	Plans          *PlanRepo
	Subscriptions  *SubscriptionRepo
	Refresh        *RefreshSessionRepo
	Audit          *AuditLogRepo
	OAuthStates    *OAuthStateRepo
	UserIdentities *UserIdentityRepo
}

// New builds a Store with all repos wired to the given pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{
		Pool:           pool,
		Users:          &UserRepo{pool: pool},
		Tenants:        &TenantRepo{pool: pool},
		Memberships:    &MembershipRepo{pool: pool},
		Plans:          &PlanRepo{pool: pool},
		Subscriptions:  &SubscriptionRepo{pool: pool},
		Refresh:        &RefreshSessionRepo{pool: pool},
		Audit:          &AuditLogRepo{pool: pool},
		OAuthStates:    &OAuthStateRepo{pool: pool},
		UserIdentities: &UserIdentityRepo{pool: pool},
	}
}

// WithTx runs fn inside a database transaction and rolls back on error.
func (s *Store) WithTx(ctx context.Context, fn func(tx pgx.Tx) error) error {
	tx, err := s.Pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// IsUniqueViolation returns true if err is a Postgres unique-constraint
// violation (SQLSTATE 23505). Used by services to translate to typed errors.
func IsUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505"
}

// IsForeignKeyViolation returns true if err is a FK violation (23503).
func IsForeignKeyViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23503"
}